const listClaims = `-- name: ListClaims :many
SELECT c.id, c.reference, c.person_id, c.program_id, c.enrollment_id,
       c.provider_organization_id, c.domain_code, c.case_id, c.fulfilment_id,
       c.authorization_id, c.current_version_no, c.status, c.service_date_from,
       c.service_date_to, c.channel, c.reject_reason_code, c.return_reason_code,
       c.review_comment_medical, c.review_comment_financial, c.closed_at, c.created_at,
       c.row_version
  FROM claim.claim c
 WHERE c.tenant_id = $1
   AND ($2::uuid[] IS NULL
        OR c.provider_organization_id = ANY($2::uuid[]))
   AND ($3::uuid IS NULL OR c.person_id = $3::uuid)
   AND ($4::uuid IS NULL OR c.case_id = $4::uuid)
   AND ($5::uuid IS NULL
        OR c.provider_organization_id = $5::uuid)
   AND ($6::text IS NULL OR c.status = $6::text)
   AND ($7::date IS NULL
        OR c.service_date_to >= $7::date)
   AND ($8::date IS NULL
        OR c.service_date_from <= $8::date)
   AND ($9::timestamptz IS NULL
        OR (c.created_at, c.id) < ($9::timestamptz, $10::uuid))
 ORDER BY c.created_at DESC, c.id DESC
 LIMIT $11
`

