const providerHasTaxIdentity = `-- name: ProviderHasTaxIdentity :one
SELECT EXISTS (
    SELECT 1
      FROM directory.tenant_organization t
      JOIN directory.organization o ON o.id = t.organization_id
     WHERE t.tenant_id = $1
       AND t.id = $2
       AND o.tax_number_hash IS NOT NULL
) AS has_tax_identity
`

type ProviderHasTaxIdentityParams struct {
	TenantID             uuid.UUID
	TenantOrganizationID uuid.UUID
}

// Whether the provider organization carries a tax identity an invoice can be raised
// against. It answers a boolean and never the number: the value is envelope-encrypted and
// the hash is a blind index, and neither of them belongs in a readiness response.
func (q *Queries) ProviderHasTaxIdentity(ctx context.Context, arg ProviderHasTaxIdentityParams) (bool, error) {
	row := q.db.QueryRow(ctx, providerHasTaxIdentity, arg.TenantID, arg.TenantOrganizationID)
	var has_tax_identity bool
	err := row.Scan(&has_tax_identity)
	return has_tax_identity, err
}

const resolveClaimEntitlementCodes = `-- name: ResolveClaimEntitlementCodes :many
SELECT m.service_definition_id, d.code AS entitlement_code
  FROM benefit.enrollment e
  JOIN benefit.plan_version v
    ON v.tenant_id = e.tenant_id
   AND v.plan_id = e.plan_id
   AND v.status = 'PUBLISHED'
   AND v.valid_period @> $1::date
  JOIN benefit.service_entitlement_mapping m
    ON m.tenant_id = v.tenant_id
   AND m.plan_version_id = v.id
  JOIN benefit.entitlement_definition d
    ON d.tenant_id = m.tenant_id
   AND d.id = m.entitlement_definition_id
 WHERE e.tenant_id = $2
   AND e.id = $3
   AND m.service_definition_id = ANY($4::uuid[])
   AND (m.valid_from IS NULL OR m.valid_from <= $1::date)
   AND (m.valid_to IS NULL OR m.valid_to > $1::date)
`

type ResolveClaimEntitlementCodesParams struct {
	ServiceDate          pgtype.Date
	TenantID             uuid.UUID
	EnrollmentID         uuid.UUID
	ServiceDefinitionIds []uuid.UUID
}

type ResolveClaimEntitlementCodesRow struct {
	ServiceDefinitionID uuid.UUID
	EntitlementCode     string
}

// Which entitlement each of these services draws on, under the plan version in force for this
// enrollment on the service date (WP-I5-05's `benefit.service_entitlement_mapping`).
//
// The claim needs it for the same reason the eligibility check does: the pricing ladder caps
// what the payer carries at the balance behind the line, and a line whose entitlement nobody
// named has no balance to be capped by. Without this the plan would appear to carry nothing
// and every member would be told they owe the whole bill.
func (q *Queries) ResolveClaimEntitlementCodes(ctx context.Context, arg ResolveClaimEntitlementCodesParams) ([]ResolveClaimEntitlementCodesRow, error) {
	rows, err := q.db.Query(ctx, resolveClaimEntitlementCodes,
		arg.ServiceDate,
		arg.TenantID,
		arg.EnrollmentID,
		arg.ServiceDefinitionIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ResolveClaimEntitlementCodesRow
	for rows.Next() {
		var i ResolveClaimEntitlementCodesRow
		if err := rows.Scan(&i.ServiceDefinitionID, &i.EntitlementCode); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

