const touchClaim = `-- name: TouchClaim :execrows
UPDATE claim.claim
   SET updated_by = $1
 WHERE tenant_id = $2
   AND id = $3
   AND row_version = $4
`

type TouchClaimParams struct {
	ActorID            uuid.NullUUID
	TenantID           uuid.UUID
	ID                 uuid.UUID
	ExpectedRowVersion int64
}

// Moves the claim's row_version without changing a field of it. It is what a line
// replacement does: the lines belong to the version, the ETag belongs to the claim, and a
// caller that replaced the lines has to be given a new token or its next If-Match is stale.
func (q *Queries) TouchClaim(ctx context.Context, arg TouchClaimParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchClaim,
		arg.ActorID,
		arg.TenantID,
		arg.ID,
		arg.ExpectedRowVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateClaimDraft = `-- name: UpdateClaimDraft :execrows
UPDATE claim.claim
   SET service_date_from = $1,
       service_date_to   = $2,
       channel           = $3,
       case_id           = $4,
       fulfilment_id     = $5,
       authorization_id  = $6,
       updated_by        = $7
 WHERE tenant_id = $8
   AND id = $9
   AND status IN ('DRAFT', 'RETURNED')
   AND row_version = $10
`

type UpdateClaimDraftParams struct {
	ServiceDateFrom    pgtype.Date
	ServiceDateTo      pgtype.Date
	Channel            string
	CaseID             uuid.NullUUID
	FulfilmentID       uuid.NullUUID
	AuthorizationID    uuid.NullUUID
	ActorID            uuid.NullUUID
	TenantID           uuid.UUID
	ID                 uuid.UUID
	ExpectedRowVersion int64
}

// The header of a claim whose current version is still a draft. The status predicate is the
// freeze: a claim that has been submitted matches no row here, and the service answers 409
// CLAIM_VERSION_FROZEN rather than quietly editing a decided statement.
func (q *Queries) UpdateClaimDraft(ctx context.Context, arg UpdateClaimDraftParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateClaimDraft,
		arg.ServiceDateFrom,
		arg.ServiceDateTo,
		arg.Channel,
		arg.CaseID,
		arg.FulfilmentID,
		arg.AuthorizationID,
		arg.ActorID,
		arg.TenantID,
		arg.ID,
		arg.ExpectedRowVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
